<?php
namespace AutoDealership\Portal;
defined('ABSPATH') || exit;

/** Server-rendered portal. All actions remain usable without JavaScript. */
final class PortalView {
	public static function text(string $ar,string $en):void {echo esc_html(PortalAccess::t($ar,$en));}
	public static function input(string $name,string $ar,string $en,string $value='',string $type='text',string $attrs=''):void {
		echo '<label>'.esc_html(PortalAccess::t($ar,$en)).'<input type="'.esc_attr($type).'" name="'.esc_attr($name).'" value="'.esc_attr($value).'" '.$attrs.'></label>';
	}
	public static function button(string $ar,string $en,string $class=''):void {echo '<button type="submit" class="adc-p-button '.esc_attr($class).'">'.esc_html(PortalAccess::t($ar,$en)).'</button>';}
	public static function badge(string $status):void {echo '<span class="adc-p-badge" data-state="'.esc_attr($status).'">'.esc_html(PortalAccess::label($status)).'</span>';}
	public static function empty(string $ar,string $en):void {echo '<div class="adc-p-empty"><span aria-hidden="true">◌</span><p>'.esc_html(PortalAccess::t($ar,$en)).'</p></div>';}
	public static function branches(int $selected=0,bool $optional=false):void {
		$branches=PortalAccess::branches();if(!$optional&&count($branches)===1&&0===(int)$branches[0]['id']){echo '<p class="adc-p-help">'.esc_html(PortalAccess::t('يتابع فريق خدمة العملاء طلبك.','Our customer care team will follow up your enquiry.')).'</p><input type="hidden" name="branch" value="0">';return;}
		echo '<label>'.esc_html(PortalAccess::t('الفرع','Branch')).'<select name="branch" '.(!$optional?'required':'').'>';
		echo '<option value="0">'.esc_html(PortalAccess::t($optional?'جميع الفروع':'اختر الفرع',$optional?'All branches':'Choose a branch')).'</option>';
		foreach($branches as $branch){if(!(int)$branch['id']){continue;}echo '<option value="'.(int)$branch['id'].'" '.selected($selected,$branch['id'],false).'>'.esc_html($branch['name']).'</option>';}
		echo '</select></label>';
	}
	public static function render():void {
		$user=wp_get_current_user();$sections=array('overview'=>['نظرة عامة','Overview'],'requests'=>['طلباتي واستفساراتي','My enquiries'],'bookings'=>['تجارب القيادة','Test drives'],'messages'=>['الرسائل','Messages'],'reviews'=>['تقييماتي','My reviews'],'profile'=>['بياناتي وأمان الحساب','Account & security'],'preferences'=>['تفضيلات التواصل','Communication preferences']);
		$section=isset($_GET['portal'])&&is_string($_GET['portal'])?sanitize_key($_GET['portal']):'overview';
		if(isset($_GET['preferences_saved'])){$section='preferences';}elseif(isset($_GET['saved'])){$section='profile';}elseif(isset($_GET['request_updated'])||isset($_GET['bookings_page'])){$section='bookings';}elseif(isset($_GET['messages_page'])){$section='requests';}
		if(!isset($sections[$section])){$section='overview';}
		echo '<div class="container adc-portal" dir="'.('ar'===PortalAccess::language()?'rtl':'ltr').'" lang="'.esc_attr(PortalAccess::language()).'"><header class="adc-p-welcome"><div><span class="adc-p-avatar" aria-hidden="true">'.esc_html(mb_substr($user->display_name,0,1)).'</span><span class="adc-p-eyebrow">'.esc_html(PortalAccess::t('مساحتك لدى المعرض','Your dealership account')).'</span><h1>'.esc_html(PortalAccess::t('مرحبًا، ','Welcome, ').$user->display_name).'</h1><p>'.esc_html(PortalAccess::t('تابع طلباتك، تواصل مع الفريق، وشاركنا تجربتك.','Follow your enquiries, talk to our team, and share your experience.')).'</p></div><a class="adc-p-button is-secondary" href="'.esc_url(wp_logout_url(home_url('/'))).'">'.esc_html(PortalAccess::t('تسجيل الخروج','Sign out')).'</a></header><div class="adc-p-layout"><nav class="adc-p-nav" aria-label="'.esc_attr(PortalAccess::t('أقسام حساب العميل','Customer account sections')).'">';
		foreach($sections as $key=>$labels){echo '<a href="'.esc_url(PortalAccess::url($key)).'" '.($section===$key?'aria-current="page"':'').'>'.esc_html(PortalAccess::t(...$labels)).'</a>';}
		echo '</nav><section class="adc-p-main" id="adc-portal-content" aria-labelledby="adc-portal-title"><h2 id="adc-portal-title">'.esc_html(PortalAccess::t(...$sections[$section])).'</h2>';Portal::flash();
		$error=$GLOBALS['cd_account_error']??'';if($error){echo '<div class="adc-p-notice is-error" role="alert">'.esc_html($error).'</div>';}
		foreach(array('saved'=>['تم تحديث بياناتك.','Your details were updated.'],'preferences_saved'=>['تم حفظ تفضيلات التواصل.','Communication preferences saved.'],'request_updated'=>['تم تحديث الحجز وإبلاغ الفريق.','Booking updated and the team notified.']) as $param=>$label){if(isset($_GET[$param])){echo '<p class="adc-p-notice is-success" data-success-notice data-notice-param="'.esc_attr($param).'" role="status">'.esc_html(PortalAccess::t(...$label)).'</p>';}}
		if(!PortalAccess::verified()&&in_array($section,array('messages','reviews'),true)){echo '<p class="adc-p-notice">'.esc_html(PortalAccess::t('يمكنك الاطلاع على سجلك. لإرسال رسالة أو تقييم، أكّد ملكية بريدك من بيانات الحساب.','You can read your history. Confirm email ownership in Account & security to send messages or reviews.')).' <a href="'.esc_url(PortalAccess::url('profile')).'">'.esc_html(PortalAccess::t('بيانات الحساب','Account details')).'</a></p>';}
		switch($section){case 'requests':self::requests('messages');break;case 'bookings':self::requests('bookings');break;case 'messages':self::messages();break;case 'reviews':self::reviews();break;case 'profile':self::profile();break;case 'preferences':self::preferences();break;default:self::overview();}
		echo '</section></div></div>';
	}
	private static function overview():void {
		global $wpdb;$uid=get_current_user_id();$requests=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}car_dealer_messages WHERE user_id=%d AND status IN ('new','read')",$uid));
		$bookings=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}car_dealer_bookings WHERE user_id=%d AND status IN ('pending','confirmed') AND CONCAT(requested_date,' ',requested_time)>=%s",$uid,current_time('mysql')));
		$unread=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.PortalAccess::table('threads')." t WHERE t.customer_id=%d AND EXISTS(SELECT 1 FROM ".PortalAccess::table('messages')." m WHERE m.thread_id=t.id AND m.visibility='public' AND m.sender_id<>%d AND m.id>COALESCE((SELECT r.last_id FROM ".PortalAccess::table('reads')." r WHERE r.thread_id=t.id AND r.user_id=%d),0))",$uid,$uid,$uid));
		echo '<div class="adc-p-stats">';foreach(array(array('requests',$requests,'طلبات قيد المتابعة','Open enquiries'),array('bookings',$bookings,'مواعيد قادمة','Upcoming appointments'),array('messages',$unread,'محادثات غير مقروءة','Unread conversations')) as $card){echo '<a class="adc-p-stat" href="'.esc_url(PortalAccess::url($card[0])).'"><strong>'.esc_html(number_format_i18n($card[1])).'</strong><span>'.esc_html(PortalAccess::t($card[2],$card[3])).'</span></a>';}echo '</div>';
		echo '<section class="adc-p-card"><h3>'.esc_html(PortalAccess::t('حسابك جاهز للمتابعة','Stay connected')).'</h3><p>'.esc_html(PortalAccess::verified()?PortalAccess::t('بريدك مؤكد. يمكنك التواصل مع الموظف المختص ومشاركة تقييمك من حسابك.','Your email is confirmed. You can message your adviser and submit reviews from your account.'):PortalAccess::t('حسابك متاح؛ أكّد ملكية البريد لتفعيل المراسلات والتقييمات.','Your account is available. Confirm email ownership to enable messaging and reviews.')).'</p><a class="adc-p-button" href="'.esc_url(PortalAccess::url(PortalAccess::verified()?'messages':'profile')).'">'.esc_html(PortalAccess::t('متابعة الآن','Continue')).'</a></section><section class="adc-p-card"><h3>'.esc_html(PortalAccess::t('آخر المستجدات','Latest updates')).'</h3>';
		$notifications=Portal::notifications();if(!$notifications){self::empty('ستظهر هنا مستجدات محادثاتك وتقييماتك.','Updates to your conversations and reviews will appear here.');}
		foreach($notifications as $notification){$message='message'===$notification['kind'];$row=$message?Conversations::row((int)$notification['object_id']):Reviews::row((int)$notification['object_id']);if(!$row||($message?!PortalAccess::can_thread($row):(int)$row['user_id']!==$uid)){continue;}echo '<p><a href="'.esc_url(PortalAccess::url($message?'messages':'reviews',$message?array('thread'=>$row['id']):array())).'">'.esc_html($message?PortalAccess::t('رسالة جديدة في محادثتك','New message in your conversation'):PortalAccess::t('تحديث على حالة تقييمك','Your review status changed')).'</a> <small>'.esc_html(get_date_from_gmt($notification['created_at'],'Y-m-d H:i')).'</small></p>';}
		echo '</section>';
	}
	private static function request_status(string $status):string {$labels=array('new'=>['جديد','New'],'read'=>['قيد المتابعة','In progress'],'completed'=>['مكتمل','Completed'],'cancelled'=>['ملغى','Cancelled'],'pending'=>['قيد الانتظار','Pending'],'confirmed'=>['مؤكد','Confirmed']);return isset($labels[$status])?PortalAccess::t(...$labels[$status]):PortalAccess::t('قيد المتابعة','In progress');}
    private static function request_kind(string $kind):string {$labels=array('contact'=>['استفسار عام','General enquiry'],'price_request'=>['طلب سعر','Price enquiry'],'finance'=>['طلب تمويل','Finance enquiry'],'finance_request'=>['طلب تمويل','Finance enquiry'],'offer_request'=>['استفسار عن عرض','Offer enquiry'],'test_drive'=>['تجربة قيادة','Test drive'],'purchase'=>['استفسار شراء','Purchase enquiry']);return isset($labels[$kind])?PortalAccess::t(...$labels[$kind]):PortalAccess::t('استفسار','Enquiry');}
    private static function requests(string $type):void {
		$page=max(1,absint($_GET[$type.'_page']??1));$result=\AutoDealership\Accounts\CustomerRequestView::page($type,$page);if(is_wp_error($result)){echo '<p role="alert">'.esc_html($result->get_error_message()).'</p>';return;}
		if(!$result['items']){self::empty('ليس لديك طلبات في هذا القسم حاليًا. استعرض السيارات أو تواصل مع فريقنا لمساعدتك.','There are no requests in this section yet. Browse the cars or contact our team for help.');}
		foreach($result['items'] as $item){echo '<article class="adc-p-card"><header class="adc-p-card-head"><h3>'.esc_html(PortalAccess::t('رقم الطلب ','Request #').$item['id']).'</h3><span class="adc-p-badge">'.esc_html(self::request_status($item['status'])).'</span></header>';
			echo '<p class="adc-p-meta">'.esc_html(self::request_kind($item['request_kind']??'contact')).'</p>';if(!empty($item['subject'])){echo '<p>'.esc_html($item['subject']).'</p>';}if($item['car_url']){echo '<a href="'.esc_url($item['car_url']).'">'.esc_html($item['car_title']).'</a>';}
			echo '<small class="adc-p-meta">'.esc_html(get_date_from_gmt($item['created_at'],'Y-m-d H:i')).'</small>';
			if('bookings'===$type){echo '<p><strong>'.esc_html(PortalAccess::t('الموعد المطلوب: ','Requested appointment: ')).'</strong><bdi>'.esc_html($item['requested_date'].' '.$item['requested_time']).'</bdi> <small>'.esc_html(wp_timezone_string()).'</small></p><p>'.esc_html(PortalAccess::t('موعد الزيارة يخضع لتأكيد الفريق. لتعديل الموعد، تواصل عبر محادثة الطلب.','Visits are subject to team confirmation. To change the time, use the request conversation.')).'</p>';}else{echo '<p class="adc-p-body">'.nl2br(esc_html($item['message'])).'</p>';}
			if($item['customer_reply']){echo '<blockquote class="adc-p-last-reply"><strong>'.esc_html(PortalAccess::t('آخر رد من المعرض','Latest team reply')).'</strong><p>'.nl2br(esc_html($item['customer_reply'])).'</p></blockquote>';}
			echo '<div class="adc-p-actions">';Portal::form('context','messages',array('kind'=>'bookings'===$type?'booking':'message','source'=>$item['id']));self::button('فتح المحادثة','Open conversation');echo '</form>';
			if('completed'===$item['status']){Portal::form('review_context','reviews',array('kind'=>'bookings'===$type?'booking':'message','source'=>$item['id']));self::button('تقييم التجربة','Review this experience','is-secondary');echo '</form>';}if($item['can_cancel']){echo '<form method="post" action="'.esc_url(PortalAccess::url('bookings')).'" data-confirm="'.esc_attr(PortalAccess::t('هل تريد إلغاء طلب تجربة القيادة؟','Cancel this test-drive request?')).'">';wp_nonce_field('cd_account_dashboard');echo '<input type="hidden" name="account_action" value="cancel_booking"><input type="hidden" name="request_id" value="'.(int)$item['id'].'">';self::button('إلغاء الطلب','Cancel request','is-secondary');echo '</form>';}
			echo '</div></article>';
		}
		self::pagination($page,$result['has_more'],PortalAccess::url('bookings'===$type?'bookings':'requests'),$type.'_page');
		$url=function_exists('car_dealer_archive_url')?car_dealer_archive_url('car'):home_url('/cars/');echo '<a class="adc-p-button is-secondary" href="'.esc_url($url).'">'.esc_html(PortalAccess::t('استعرض السيارات','Browse cars')).'</a>';
	}
	public static function pagination(int $page,bool $more,string $url,string $key='portal_page'):void {
		echo '<nav class="adc-p-pagination" aria-label="'.esc_attr(PortalAccess::t('صفحات النتائج','Result pages')).'">';if($page>1){echo '<a class="adc-p-button is-secondary" href="'.esc_url(add_query_arg($key,$page-1,$url)).'">'.esc_html(PortalAccess::t('السابق','Previous')).'</a>';}if($more){echo '<a class="adc-p-button is-secondary" href="'.esc_url(add_query_arg($key,$page+1,$url)).'">'.esc_html(PortalAccess::t('التالي','Next')).'</a>';}echo '</nav>';
	}
	public static function messages(bool $admin=false):void {
		$id=absint($_GET['thread']??0);if($id){self::conversation($id,$admin);return;}
		$page=max(1,absint($_GET['portal_page']??1));$status=isset($_GET['status'])&&is_string($_GET['status'])?sanitize_key($_GET['status']):'';$owner=isset($_GET['owner'])&&is_scalar($_GET['owner'])?(int)$_GET['owner']:-1;$branch=absint($_GET['branch']??0);
		$rows=Conversations::list($page,$status,$admin?$owner:-1,$admin?$branch:0);$more=count($rows)>20;
		if(!$rows){self::empty('لا توجد محادثات حاليًا. يمكنك فتح محادثة مرتبطة بطلبك أو بدء استفسار جديد.','No conversations yet. Open a conversation from a request or start a new enquiry.');}
		foreach(array_slice($rows,0,20) as $row){$url=$admin?admin_url('admin.php?page=adc-conversations&thread='.$row['id']):PortalAccess::url('messages',array('thread'=>$row['id']));echo '<a class="adc-p-thread-card" href="'.esc_url($url).'"><div><h3>'.esc_html(Conversations::subject($row)).'</h3><small>'.esc_html(get_date_from_gmt($row['updated_at'],'Y-m-d H:i')).'</small></div><div>';if($row['unread']){echo '<span class="adc-p-unread">'.esc_html(PortalAccess::t('جديد','New')).'</span>';}self::badge($row['status']);echo '</div></a>';}
		$base=$admin?admin_url('admin.php?page=adc-conversations'):PortalAccess::url('messages');self::pagination($page,$more,add_query_arg(array('status'=>$status,'owner'=>$owner,'branch'=>$branch),$base));
		if(!$admin&&PortalAccess::verified()){echo '<section class="adc-p-card"><h3>'.esc_html(PortalAccess::t('استفسار جديد','New enquiry')).'</h3><p>'.esc_html(PortalAccess::t('للمتابعة حول سيارة أو موعد سابق، افتح المحادثة من طلبك حتى يبقى السجل في مكان واحد.','For an existing vehicle enquiry or appointment, open the conversation from your request to keep its history together.')).'</p>';Portal::form('context','messages',array('kind'=>'general'));self::input('subject','موضوع الاستفسار','Subject','','text','required maxlength="190"');self::branches();self::button('بدء المحادثة','Start conversation');echo '</form></section>';}
	}
	public static function conversation(int $id,bool $admin=false):void {
		$after=absint($_GET['after']??0);$detail=Conversations::detail($id,$after);if(is_wp_error($detail)){echo '<p class="adc-p-notice is-error" role="alert">'.esc_html($detail->get_error_message()).'</p>';return;}
		$row=Conversations::row($id);$back=$admin?admin_url('admin.php?page=adc-conversations'):PortalAccess::url('messages');echo '<a href="'.esc_url($back).'">'.esc_html(PortalAccess::t('كل المحادثات','All conversations')).'</a><section class="adc-p-card adc-p-conversation" data-thread="'.$id.'" data-after="'.$after.'"><header class="adc-p-card-head"><div><h3>'.esc_html($detail['subject']).'</h3><p>'.esc_html(PortalAccess::t('المتابعة مع: ','Your adviser: ').$detail['owner']).'</p></div><span data-thread-status>';self::badge($detail['status']);echo '</span></header>';
		if($row['car_id']&&\AutoDealership\Inventory\PublicCatalog::is_post_publicly_eligible((int)$row['car_id'])){echo '<p><a href="'.esc_url(get_permalink($row['car_id'])).'">'.esc_html(get_the_title($row['car_id'])).'</a></p>';}
		echo '<p class="adc-p-help">'.esc_html(PortalAccess::t('لا ترسل كلمات المرور أو بيانات بطاقتك البنكية أو مستندات حساسة. إغلاق المحادثة لا يلغي طلبك أو موعدك.','Do not send passwords, bank card details, or sensitive documents. Closing a conversation does not cancel your request or appointment.')).'</p><div class="adc-p-messages" aria-label="'.esc_attr(PortalAccess::t('سجل المحادثة','Conversation history')).'" tabindex="0">';$last=$after;$public=0;
		foreach($detail['messages'] as $message){self::message($message);$last=max($last,(int)$message['id']);if('public'===$message['visibility']){$public=(int)$message['id'];}}echo '</div><p class="adc-p-poll-status" role="status" aria-live="polite"></p><button type="button" class="adc-p-button is-secondary" data-refresh-thread>'.esc_html(PortalAccess::t('تحديث المحادثة','Refresh conversation')).'</button>';
		if($detail['has_more']){$url=add_query_arg(array('thread'=>$id,'after'=>$last),$back);echo '<a class="adc-p-button is-secondary" data-load-more href="'.esc_url($url).'">'.esc_html(PortalAccess::t('الرسائل التالية','Next messages')).'</a>';}
		{Portal::form('read','messages',array('id'=>$id,'last'=>$public),$admin);echo '<span class="adc-p-read-form">';self::button('تحديد المعروض كمقروء','Mark displayed messages as read','is-secondary');echo '</span></form>';}
		if($detail['can_reply']){
			$draft=Portal::draft('send',$id);Portal::form('send','messages',array('id'=>$id,'request_key'=>$draft['request_key']??wp_generate_uuid4()),$admin);echo '<div class="adc-p-composer"'.('closed'===$detail['status']?' hidden':'').'><label>'.esc_html(PortalAccess::t('رسالتك','Your message')).'<textarea name="body" rows="4" required maxlength="4000">'.esc_textarea($draft['body']??'').'</textarea></label>';
			if($admin){echo '<label class="adc-p-check"><input type="checkbox" name="internal" value="1">'.esc_html(PortalAccess::t('ملاحظة داخلية — لن تظهر للعميل ولن يُرسل إشعار بها','Internal note — hidden from the customer; no notification')).'</label>';}
			self::button('إرسال الرسالة','Send message');echo '</div></form>';
		}
		if($detail['can_close']){Portal::form('closed'===$detail['status']?'reopen':'close','messages',array('id'=>$id,'revision'=>$detail['revision']),$admin);self::button('closed'===$detail['status']?'إعادة فتح المحادثة':'إغلاق المحادثة','closed'===$detail['status']?'Reopen conversation':'Close conversation','is-secondary');echo '</form>';
		}
		if($admin&&$detail['can_assign']){Portal::form('assign','messages',array('id'=>$id,'revision'=>$detail['revision']),true);echo '<label>'.esc_html(PortalAccess::t('الموظف المسؤول','Assigned adviser')).'<select name="owner"><option value="0">'.esc_html(PortalAccess::t('غير مسند','Unassigned')).'</option>';foreach(get_users(array('capability'=>'adc_reply_conversations','number'=>200,'fields'=>array('ID','display_name'))) as $staff){if(!\AutoDealership\Security\BranchScope::allows((int)$row['branch_id'],(int)$staff->ID)){continue;}echo '<option value="'.(int)$staff->ID.'" '.selected($row['owner_id'],$staff->ID,false).'>'.esc_html($staff->display_name).'</option>';}echo '</select></label>';self::button('حفظ الإسناد','Save assignment','is-secondary');echo '</form>';}
		if($admin&&current_user_can('manage_options')&&'general'===$row['kind']){echo '<details class="adc-p-card"><summary>'.esc_html(PortalAccess::t('توجيه المحادثة إلى فرع','Route conversation to a branch')).'</summary>';if(0===(int)PortalAccess::branches()[0]['id']){echo '<p>'.esc_html(PortalAccess::t('يتابع الأدمن خدمة العملاء حاليًا. أضف فروع العمليات من إعدادات المنصة ثم وجّه المحادثة وأسند الموظف المختص.','The administrator currently handles customer care. Add operational branches in platform settings, then route the conversation and assign an adviser.')).'</p>';}else{Portal::form('route','messages',array('id'=>$id,'revision'=>$detail['revision']),true);self::branches((int)$row['branch_id']);self::button('حفظ الفرع وإعادة الإسناد','Save branch and reset assignment','is-secondary');echo '</form>';}echo '</details>';}
		echo '</section>';
	}
	public static function message(array $message):void {
		echo '<article class="adc-p-message '.(!empty($message['mine'])?'is-mine ':'').('internal'===$message['visibility']?'is-internal':'').'" data-message-id="'.(int)$message['id'].'" data-visibility="'.esc_attr($message['visibility']).'"><header><strong>'.esc_html($message['sender_label']).'</strong><time>'.esc_html(get_date_from_gmt($message['created_at'],'Y-m-d H:i')).'</time>'.('internal'===$message['visibility']?'<span>'.esc_html(PortalAccess::t('ملاحظة داخلية','Internal note')).'</span>':'').'</header><p>'.nl2br(esc_html($message['body'])).'</p></article>';
	}
	private static function reviews():void {
		echo '<p>'.esc_html(PortalAccess::t('شاركنا رأيك في تجربتك. يُراجع الفريق التقييم قبل نشره، ويظهر اسم العرض والنص والتقييم فقط. يمكنك تعديل رأيك أو سحب موافقة النشر في أي وقت.','Share feedback about your experience. Our team reviews submissions before publication. Only your display name, text and rating are published. You can edit your feedback or withdraw publication consent at any time.')).'</p>';
		$requested=Reviews::context(absint($_GET['context']??0));$page=max(1,absint($_GET['portal_page']??1));$rows=Reviews::mine($page);$edit=absint($_GET['review']??0);$selected=Reviews::owned($edit,$requested['id']??0);
		foreach(array_slice($rows,0,20) as $row){if($edit===(int)$row['id']||($requested&&(int)$row['thread_id']===(int)$requested['id'])){$selected=$row;}echo '<article class="adc-p-card"><header class="adc-p-card-head"><h3>'.esc_html($row['display_name']).' · '.(int)$row['rating'].'/5</h3>';self::badge($row['status']);echo '</header><p class="adc-p-body">'.nl2br(esc_html($row['body'])).'</p>';if($row['reason']){echo '<p class="adc-p-notice">'.esc_html(PortalAccess::t('ملاحظة المراجعة: ','Review note: ').$row['reason']).'</p>';}if($row['public_version']&&$row['current_version']!==$row['public_version']){echo '<p>'.esc_html(PortalAccess::t('تبقى النسخة المعتمدة السابقة منشورة حتى اعتماد التعديل.','Your previous approved version stays published until the edit is approved.')).'</p>';}
			echo '<div class="adc-p-actions"><a class="adc-p-button is-secondary" href="'.esc_url(PortalAccess::url('reviews',array('review'=>$row['id']))).'">'.esc_html(PortalAccess::t('تعديل تقييمي','Edit my review')).'</a>';if($row['consent']){Portal::form('withdraw','reviews',array('id'=>$row['id'],'revision'=>$row['revision']));self::button('سحب موافقة النشر','Withdraw publication consent','is-secondary');echo '</form>';}echo '</div></article>';}
		self::pagination($page,count($rows)>20,PortalAccess::url('reviews'));if(!PortalAccess::verified()){return;}$draft=Portal::draft('review',$selected['id']??0);$values=array_merge($selected??array(),$draft);if(isset($draft['name'])){$values['display_name']=$draft['name'];}if(!$rows){self::empty('لم ترسل تقييمًا بعد. يسعدنا الاستماع إلى تجربتك.','You have not submitted a review yet. We would love to hear about your experience.');}
		echo '<section class="adc-p-card" id="review-editor"><h3>'.esc_html($selected?PortalAccess::t('تعديل التقييم وإرساله للمراجعة','Edit and resubmit for review'):PortalAccess::t('اكتب تقييمك','Write a review')).'</h3>';Portal::form('review','reviews',array('id'=>$selected['id']??0,'revision'=>$selected['revision']??0,'thread'=>$selected['thread_id']??($requested['id']??0)));self::input('name','اسم العرض العام','Public display name',$values['display_name']??wp_get_current_user()->display_name,'text','required maxlength="100"');
		if($selected||$requested){echo '<input type="hidden" name="branch" value="'.(int)($selected['branch_id']??$requested['branch_id']).'"><p>'.esc_html(PortalAccess::t('تقييم تجربة مرتبطة بطلبك المكتمل','Review of your completed enquiry')).'</p>';}else{self::branches(absint($draft['branch']??0));}
		echo '<label>'.esc_html(PortalAccess::t('التقييم','Rating')).'<select name="rating" required>';for($i=5;$i>=1;$i--){echo '<option value="'.$i.'" '.selected($values['rating']??5,$i,false).'>'.$i.' / 5</option>';}echo '</select></label><label>'.esc_html(PortalAccess::t('لغة التقييم','Review language')).'<select name="locale">';foreach(array('ar'=>'العربية','en'=>'English') as $lang=>$label){echo '<option value="'.$lang.'" '.selected($values['locale']??PortalAccess::language(),$lang,false).'>'.$label.'</option>';}echo '</select></label><label>'.esc_html(PortalAccess::t('تجربتك مع المعرض','Your experience')).'<textarea name="body" rows="5" minlength="10" maxlength="3000" required>'.esc_textarea($values['body']??'').'</textarea></label><label class="adc-p-check"><input type="checkbox" name="consent" value="1" required>'.esc_html(PortalAccess::t('أوافق على نشر اسم العرض والتقييم ونص رأيي على الموقع بعد المراجعة، وأؤكد خلو النص من بيانات حساسة.','I consent to publication of my display name, rating and review text after moderation, and confirm the text contains no sensitive information.')).'</label>';self::button('إرسال للمراجعة','Submit for review');echo '</form></section>';
		global $wpdb;$wpdb->query($wpdb->prepare('UPDATE '.PortalAccess::table('notifications')." SET read_at=%s WHERE user_id=%d AND kind='review' AND read_at IS NULL",current_time('mysql',true),get_current_user_id()));
	}
	private static function profile():void {
		$user=wp_get_current_user();echo '<section class="adc-p-card"><h3>'.esc_html(PortalAccess::t('حالة البريد الإلكتروني','Email status')).'</h3><p><bdi>'.esc_html($user->user_email).'</bdi></p><p>'.esc_html(PortalAccess::verified()?PortalAccess::t('تم تأكيد ملكية البريد الإلكتروني.','Email ownership confirmed.'):PortalAccess::t('لم يُسجل تأكيد ملكية البريد بعد. حسابك وطلباتك السابقة محفوظة.','Email ownership has not yet been confirmed. Your account and previous enquiries remain available.')).'</p>';
		if(!PortalAccess::verified()){Portal::form('ownership','profile');self::button('إرسال رابط تأكيد البريد','Send email confirmation link');echo '</form>';}echo '</section><section class="adc-p-card"><h3>'.esc_html(PortalAccess::t('بياناتي الشخصية','Personal details')).'</h3><form class="adc-p-form" method="post" action="'.esc_url(PortalAccess::url('profile')).'">';wp_nonce_field('cd_account_dashboard');self::input('display_name','الاسم','Name',$user->display_name,'text','required maxlength="250" autocomplete="name"');self::input('phone','رقم الجوال','Mobile number',(string)get_user_meta($user->ID,'car_dealer_phone',true),'tel','autocomplete="tel" dir="ltr"');self::button('حفظ البيانات','Save details');echo '</form><p><a href="'.esc_url(wp_lostpassword_url(add_query_arg('cd_account','login',home_url('/')))).'">'.esc_html(PortalAccess::t('إعادة تعيين كلمة المرور','Reset password')).'</a></p><p class="adc-p-help">'.esc_html(PortalAccess::t('لتغيير البريد أو طلب نسخة من بياناتك أو حذفها، تواصل مع فريق المعرض من محادثة خاصة.','To change your email or request a copy or erasure of your data, contact our team in a private conversation.')).'</p></section>';
	}
	private static function preferences():void {
		$p=adc_customer_current_preferences();if(is_wp_error($p)){echo '<p role="alert">'.esc_html($p->get_error_message()).'</p>';return;}
		echo '<section class="adc-p-card"><p>'.esc_html(PortalAccess::t('اختر ما إذا كنت ترغب في استقبال العروض والأخبار. رسائل الحساب والطلبات اللازمة للخدمة لا تتأثر بهذا الاختيار.','Choose whether to receive offers and news. Essential account and enquiry messages are unaffected.')).'</p><form class="adc-p-form" method="post" action="'.esc_url(PortalAccess::url('preferences')).'">';wp_nonce_field('cd_account_dashboard');echo '<input type="hidden" name="account_action" value="save_preferences"><label>'.esc_html(PortalAccess::t('لغة الرسائل المفضلة','Preferred email language')).'<select name="newsletter_language">';foreach(array('ar'=>'العربية','en'=>'English') as $lang=>$name){echo '<option value="'.$lang.'" '.selected($p['newsletter_language']??'ar',$lang,false).'>'.$name.'</option>';}echo '</select></label><fieldset><legend>'.esc_html(PortalAccess::t('التواصل التسويقي','Marketing communication')).'</legend>';
		$on=!empty($p['consent_marketing'])||'pending'===($p['subscription_status']??'');foreach(array('1'=>['أوافق على استقبال العروض والأخبار التسويقية.','I agree to receive marketing offers and news.'],'0'=>['لا أرغب في استقبال تواصل تسويقي.','I do not want marketing communication.']) as $value=>$label){echo '<label class="adc-p-check"><input type="radio" name="consent_marketing" value="'.esc_attr((string)$value).'" required '.checked($on,'1'===(string)$value,false).'>'.esc_html(PortalAccess::t(...$label)).'</label>';}echo '</fieldset>';
		if('pending'===($p['subscription_status']??'')){echo '<p>'.esc_html(PortalAccess::t('طلب الاشتراك ينتظر تأكيد البريد.','Your subscription is awaiting email confirmation.')).' <a href="'.esc_url(\AutoDealership\Accounts\EmailVerification::page_url('newsletter')).'">'.esc_html(PortalAccess::t('طلب رابط جديد','Request a new link')).'</a></p>';}
		self::button('حفظ التفضيلات','Save preferences');echo '</form></section>';
	}
}
